code:
def solve(coins, amount):
    # DP bottom-up: dp[x] = min coins to make x, init inf
    if amount < 0:
        return -1
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue
        for x in range(coin, amount+1):
            if dp[x-coin] + 1 < dp[x]:
                dp[x] = dp[x-coin] + 1
    return dp[amount] if dp[amount] != float('inf') else -1

