def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings representing integers or operators + - * /
    Returns integer result; division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Python division truncates toward zero via int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

