def solve(coins, amount):
    # Minimum number of coins to make up amount using unlimited supply.
    # DP bottom-up approach. Complexity O(amount * len(coins)).
    if amount < 0:
        return -1
    # Initialize dp where dp[i] is minimal coins for amount i.
    # Use a large sentinel for impossible.
    INF = amount + 1  # larger than any possible count
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # try using coin c
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

