    """Simplify an absolute Unix path.
    Implements the typical canonical path resolution using a stack.
    """
    # Guard against non‑string input – treat as root.
    if not isinstance(path, str):
        return '/'
    # The path is assumed absolute; if not, prepend a slash to simplify logic.
    if not path.startswith('/'):
        path = '/' + path
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components caused by '//' and current directory.
            continue
        if part == '..':
            # Go up one level if possible.
            if stack:
